        ["Vendor Number", "VendorNumber"],
        ["Order Number", "OrderNumber"],
        ["Item Number", "ItemNumber"],
        ["GL Account", "GLAccount"],
        ["Ordered Amount", "OrderedAmount"],
        ["Delivered Amount", "DeliveredAmount"],
        ["Invoiced Amount", "InvoicedAmount"],
